-- Social Guard Educational Seed Data

-- 1. Assessment Questions & Options
-- Category: password
INSERT INTO public.assessment_questions (id, category, question_text, explanation, weight, order_index) VALUES
('a1000000-0000-0000-0000-000000000001', 'password', 'Do you use unique, distinct passwords for each of your social media accounts?', 'Reusing passwords across multiple accounts creates a cascade risk where a breach on one site compromises all your social accounts.', 2.0, 1),
('a1000000-0000-0000-0000-000000000002', 'password', 'How often do you update passwords for sensitive social media accounts?', 'Periodic updates combined with strong passphrases reduce the exposure window of stolen credentials.', 1.5, 2),
('a1000000-0000-0000-0000-000000000003', 'password', 'Do you store your passwords in a secure Password Manager instead of browser auto-fill or written notes?', 'Password managers encrypt vault data locally using master key derivating algorithms (e.g. PBKDF2/Argon2).', 1.5, 3),

-- Category: mfa
('a1000000-0000-0000-0000-000000000004', 'mfa', 'Is Multi-Factor Authentication (MFA/2FA) enabled on all primary social accounts?', 'MFA blocks up to 99% of automated account takeover attempts.', 2.0, 4),
('a1000000-0000-0000-0000-000000000005', 'mfa', 'What type of Multi-Factor Authentication do you primarily use?', 'Authenticator apps (TOTP) or hardware keys (FIDO2) are far more secure than SMS text messages, which can be hijacked via SIM swapping.', 1.5, 5),
('a1000000-0000-0000-0000-000000000006', 'mfa', 'Have you downloaded and safely stored offline backup recovery codes for your accounts?', 'Backup codes ensure you retain access if your primary phone or authenticator app is lost or damaged.', 1.5, 6),

-- Category: privacy
('a1000000-0000-0000-0000-000000000007', 'privacy', 'Are your phone number and personal email address hidden from public search on your social profiles?', 'Public contact info is harvested by attackers for targeted spear-phishing and SMS spoofing.', 1.5, 7),
('a1000000-0000-0000-0000-000000000008', 'privacy', 'Do you restrict who can view your friend/follower lists and full date of birth?', 'Attackers build social graphs and answer security questions using publicly visible birthdates, family ties, and pet names.', 1.5, 8),
('a1000000-0000-0000-0000-000000000009', 'privacy', 'Do you turn off real-time location tagging on public social media posts?', 'Real-time geotagging exposes your physical location, routines, and physical security vulnerabilities.', 1.0, 9),

-- Category: phishing
('a1000000-0000-0000-0000-000000000010', 'phishing', 'Do you inspect the full domain address of login links before typing account credentials?', 'Phishers use lookalike domains (typosquatting like instagram-verify-center.com) to steal login tokens.', 2.0, 10),
('a1000000-0000-0000-0000-000000000011', 'phishing', 'How do you respond to urgent DMs claiming your account will be suspended unless you click a link immediately?', 'Urgency and fear are classic social engineering triggers designed to bypass critical thinking.', 2.0, 11),

-- Category: applications
('a1000000-0000-0000-0000-000000000012', 'applications', 'Do you regularly audit third-party apps connected via OAuth (e.g., "Log in with Facebook/Google")?', 'Connected third-party apps maintain active token permissions that can access your profile even after password changes.', 1.5, 12),

-- Category: recovery
('a1000000-0000-0000-0000-000000000013', 'recovery', 'Are your recovery email address and phone number up to date and protected with MFA?', 'If an attacker compromises your recovery email, they can perform password resets on your social media accounts.', 1.5, 13),

-- Category: awareness
('a1000000-0000-0000-0000-000000000014', 'awareness', 'Do you review active login sessions and device history periodically on platforms like Meta, X, and Google?', 'Checking active sessions allows you to spot unauthorized device logins and terminate them instantly.', 1.0, 14);

-- Assessment Options
INSERT INTO public.assessment_options (id, question_id, option_text, score_value, risk_indicator, finding_title, finding_recommendation) VALUES
-- Q1 Passwords
('b1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'Yes, every account has a distinct, strong password.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 'I use a few variation passwords across accounts.', 40, 'MEDIUM', 'Password Reuse Detected', 'Create unique passwords or passphrases for each social account to prevent credential stuffing attacks.'),
('b1000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000001', 'No, I use the exact same password everywhere.', 0, 'HIGH', 'Severe Password Reuse Risk', 'Immediately update your social accounts with unique, random passwords generated by a password manager.'),

-- Q2 Password Updates
('b1000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000002', 'I update them if exposed or at least annually.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000002', 'Only when forced by a system prompt.', 60, 'LOW', 'Irregular Password Maintenance', 'Audit your account breach status on HaveIBeenPwned and update passwords when breaches occur.'),
('b1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000002', 'I have used the same passwords for over 3 years.', 20, 'MEDIUM', 'Outdated Account Credentials', 'Refresh your passwords and use longer passphrases (16+ characters).'),

-- Q3 Password Manager
('b1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 'Yes, I use a dedicated encrypted Password Manager.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000003', 'I rely on browser default auto-fill.', 70, 'LOW', 'Browser Password Storage', 'Consider switching to a dedicated zero-knowledge password manager with master passphrase protection.'),
('b1000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000003', 'No, I memorize them or write them in unencrypted notes.', 20, 'HIGH', 'Unsafe Password Storage', 'Store credentials in an encrypted password manager instead of plain text notes.'),

-- Q4 MFA Status
('b1000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000004', 'Yes, enabled on all social media accounts.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000004', 'Only enabled on some main accounts.', 50, 'MEDIUM', 'Incomplete MFA Coverage', 'Turn on MFA across all remaining social channels including Instagram, X, Facebook, and LinkedIn.'),
('b1000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000004', 'No, MFA is disabled on all accounts.', 0, 'HIGH', 'MFA Not Enabled', 'Enable multi-factor authentication immediately on all social accounts to prevent simple password theft.'),

-- Q5 MFA Type
('b1000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000005', 'Authenticator App (TOTP) or Security Key (FIDO2/WebAuthn).', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000005', 'SMS text message codes.', 60, 'MEDIUM', 'SMS 2FA Vulnerability', 'Upgrade from SMS-based 2FA to a dedicated Authenticator App (e.g. 1Password, Google Authenticator) to protect against SIM swapping.'),
('b1000000-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000005', 'Email code verification only.', 50, 'LOW', 'Email 2FA Dependence', 'Avoid relying solely on email for 2FA, as email account compromise leads to immediate social takeover.'),

-- Q6 Backup Codes
('b1000000-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000006', 'Yes, saved securely in an offline encrypted vault.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000006', 'I generated them but am unsure where they are stored.', 40, 'LOW', 'Unverified Backup Codes', 'Locate or regenerate your 2FA backup recovery codes and store them in a secure location.'),
('b1000000-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000006', 'No, I have never generated or stored backup codes.', 10, 'MEDIUM', 'Missing Account Recovery Safeguards', 'Generate 2FA recovery backup codes for your account now to prevent lockouts.'),

-- Q7 Phone/Email Exposure
('b1000000-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000007', 'Hidden from public view and strictly set to private/friends-only.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000007', 'Visible to friends of friends or semi-publicly.', 50, 'LOW', 'Semi-Public Contact Details', 'Restrict contact detail visibility to private or only trusted connections.'),
('b1000000-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000007', 'Publicly visible on my profiles.', 10, 'HIGH', 'Public Contact Information Exposure', 'Remove phone numbers and personal emails from public bio fields and search visibility.'),

-- Q8 Friends list & Birthdate
('b1000000-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000008', 'Restricted to Only Me or Private.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000008', 'Full birthdate and friend list are publicly visible.', 20, 'MEDIUM', 'Public Profile Details Exposure', 'Hide your full birth year and friend list to prevent social engineering impersonation attacks.'),

-- Q9 Location Tagging
('b1000000-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000009', 'Never post real-time location or delay location tags.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000009', 'Frequently post live location tags.', 30, 'LOW', 'Real-Time Location Exposure', 'Delay tagging locations until after leaving physical venues.'),

-- Q10 Domain verification
('b1000000-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000010', 'Always verify the exact address bar URL, HTTPS protocol, and domain spellings.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000010', 'Rarely check the address bar URL before entering details.', 20, 'HIGH', 'Susceptible to Phishing Links', 'Always inspect the exact URL domain in your browser bar before typing passwords.'),

-- Q11 Suspicious DMs
('b1000000-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000011', 'Never click embedded links; navigate directly to official app settings.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000011', 'Sometimes click out of fear of account loss.', 10, 'HIGH', 'Urgency Trap Risk', 'Social media platforms will never ask for credentials via direct message links. Report and ignore urgent DMs.'),

-- Q12 Third-Party OAuth Apps
('b1000000-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000012', 'Yes, I review and revoke unused third-party app access monthly.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000012', 'Never audited connected third-party apps.', 30, 'MEDIUM', 'Unmonitored Third-Party App Permissions', 'Go to your account settings ("Apps and Websites") and revoke access for old or untrusted third-party services.'),

-- Q13 Recovery Security
('b1000000-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000013', 'Yes, recovery contact points are current and protected with MFA.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000013', 'Recovery email is old or lacks 2FA.', 30, 'HIGH', 'Vulnerable Recovery Email', 'Secure your primary recovery email account with MFA immediately, as it controls all social account resets.'),

-- Q14 Session Audits
('b1000000-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000014', 'Yes, regularly check active devices and terminate unknown sessions.', 100, 'NONE', NULL, NULL),
('b1000000-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000014', 'No, never checked active session history.', 40, 'LOW', 'Unmonitored Login Activity', 'Check security settings ("Where You''re Logged In") to confirm no unauthorized devices hold active sessions.');

-- 2. Phishing Lab Scenarios
INSERT INTO public.phishing_scenarios (id, title, context_type, message_sender, message_content, option_choices, correct_option_id, explanation, difficulty) VALUES
('c1000000-0000-0000-0000-000000000001', 
 'Urgent Instagram Copyright Violation Notice', 
 'Direct Message / Email', 
 'Instagram Copyright Support <notice@meta-copyright-appeals-center.com>', 
 'URGENT: Your post #84920 has breached trademark rights. Your account will be permanently disabled within 24 hours. Submit your appeal immediately at https://meta-copyright-appeals-center.com/appeal?user=yourname', 
 '[{"id":"opt1","text":"Click the link and fill out the appeal form immediately."},{"id":"opt2","text":"Ignore the email and report it as phishing."},{"id":"opt3","text":"Reply with your account password to verify ownership."},{"id":"opt4","text":"Click the link to check if it looks legitimate."}]'::jsonb,
 'opt2',
 'Red Flags Detected:\n1. Sender Address: "meta-copyright-appeals-center.com" is NOT an official Meta domain (official notices come from instagram.com or meta.com).\n2. Artificial Urgency: "disabled within 24 hours" forces impulsive actions.\n3. External Link: Official platforms send in-app notifications in your Account Status settings, not external phishing links.',
 'EASY'),

('c1000000-0000-0000-0000-000000000002', 
 'X (Twitter) Blue Badge Verification Alert', 
 'Direct Message', 
 'X Verification Bot (@X_Verify_Official_2026)', 
 'Congratulations! You are eligible for a free verified checkmark renewal. Please confirm your credentials within 2 hours at http://x-verify-badge-claim.net/auth', 
 '[{"id":"opt1","text":"Click link and enter password to claim checkmark."},{"id":"opt2","text":"Verify through official X Settings under Account > Subscriptions."},{"id":"opt3","text":"Send your phone number to the bot."},{"id":"opt4","text":"Forward the message to your friends."}]'::jsonb,
 'opt2',
 'Red Flags Detected:\n1. Unverified DM Handle: Official platforms never contact users via informal bot accounts asking for credentials in DMs.\n2. Non-HTTPS / Suspicious URL: "http://x-verify-badge-claim.net" uses HTTP and an untrusted domain name.\n3. Safe Behavior: Always manage subscription status inside official app settings directly.',
 'MEDIUM'),

('c1000000-0000-0000-0000-000000000003', 
 'Facebook Friend Urgent Financial Emergency Request', 
 'Messenger Direct Message', 
 'Sarah Jenkins (Friend Account)', 
 'Hey! I am stuck at the airport overseas, lost my wallet and my phone is dying. Can you Zelle me $200 right away? I will pay you back as soon as I get home tonight!', 
 '[{"id":"opt1","text":"Immediately send money via Zelle to help your friend."},{"id":"opt2","text":"Call Sarah directly or verify through a separate trusted channel before sending anything."},{"id":"opt3","text":"Ask for her credit card details."},{"id":"opt4","text":"Send half the requested amount."}]'::jsonb,
 'opt2',
 'Red Flags Detected:\n1. Account Takeover / Impersonation: Hackers frequently compromise friend accounts to send mass financial scam DMs.\n2. Pressure Tactics: Emergencies (lost wallet, stranded at airport) bypass normal skepticism.\n3. Safe Rule: Always verify emergency money requests via phone call or video chat before taking action.',
 'HARD');

-- 3. Educational Training Modules
INSERT INTO public.training_modules (id, title, slug, category, summary, content, quiz, estimated_minutes) VALUES
('d1000000-0000-0000-0000-000000000001',
 'Recognizing Social Media Phishing & Spear Phishing',
 'phishing-fundamentals',
 'Phishing',
 'Learn to spot fake copyright claims, urgent verification scams, and malicious URLs targeted at social media accounts.',
 '{"sections": [{"title": "What is Social Media Phishing?", "body": "Phishing is the practice of crafting deceptive communications (emails, DMs, text messages) designed to trick users into handing over login credentials, 2FA backup codes, or session cookies."}, {"title": "Top Phishing Vectors", "items": ["Fake Copyright Violation Claims", "Verification Badge Scams", "Influencer Collaboration / Sponsor Offers", "Security Alert Impersonations"]}, {"title": "Key Indicators of Phishing", "items": ["Domain Mismatch: Look closely at hostnames (e.g., instagram-support-portal.net instead of instagram.com).", "Artificial Urgency: Claims like ''24 Hours to Respond or Account Deleted''.", "Credential Requests via Web Forms outside official apps."]}]}'::jsonb,
 '[{"question": "Where should you check official copyright or violation notices for your Instagram account?", "options": ["Via links in unsolicited DMs", "In official App Settings under Settings > Account > Account Status", "On third-party appeal web forms", "By emailing back the sender"], "correctIndex": 1, "explanation": "Official Meta notices appear directly in your in-app Account Status menu, never exclusively via external third-party links."}]'::jsonb,
 5),

('d1000000-0000-0000-0000-000000000002',
 'Password Hygiene & Passphrase Architecture',
 'password-security',
 'Password Security',
 'Master the science of memorable high-entropy passphrases and secure password managers.',
 '{"sections": [{"title": "Why Complexity Rules Have Failed", "body": "Traditional short passwords with forced numbers and symbols (e.g. P@ssw0rd!1) are easily cracked by modern GPU hash-cracking arrays. Passphrases consisting of 4+ random words offer vastly superior entropy."}, {"title": "The Power of Passphrases", "body": "Example: ''battery-staple-correct-horse'' is extremely hard for computers to crack yet easy for humans to remember."}, {"title": "Password Manager Best Practices", "items": ["Use a zero-knowledge encrypted vault.", "Enable hardware key (YubiKey) or TOTP on your password vault.", "Never reuse passwords across social platforms."]}]}'::jsonb,
 '[{"question": "Which password is mathematically stronger against brute-force attacks?", "options": ["Admin2024!", "correct-horse-battery-staple-2026", "P@ss123", "Secret_1"], "correctIndex": 1, "explanation": "Longer passphrases create exponential combinations (entropy), making brute-force cracking mathematically infeasible."}]'::jsonb,
 6),

('d1000000-0000-0000-0000-000000000003',
 'Multi-Factor Authentication (MFA) & SIM Swapping',
 'mfa-protection',
 'MFA',
 'Understand why SMS 2FA is vulnerable to SIM swapping and how to set up hardware keys and TOTP apps.',
 '{"sections": [{"title": "Understanding Multi-Factor Authentication", "body": "Authentication factors are based on: 1. Something you know (Password), 2. Something you have (Authenticator app / Hardware key), 3. Something you are (Biometrics)."}, {"title": "The Danger of SMS 2FA", "body": "Attackers can bribe or trick mobile carrier representatives into porting your phone number to an attacker SIM card (SIM swapping), intercepting SMS 2FA codes instantly."}, {"title": "Recommended 2FA Methods", "items": ["Top Choice: Hardware Security Keys (FIDO2 / WebAuthn)", "Strong Choice: Authenticator Apps (TOTP like 1Password, Google Authenticator)", "Avoid: Plain SMS text codes where possible"]}]}'::jsonb,
 '[{"question": "Why is SMS-based 2FA considered less secure than Authenticator Apps?", "options": ["SMS uses too much phone battery", "SMS codes can be intercepted via SIM swapping attacks at the carrier level", "SMS codes do not expire", "SMS is not supported on iPhones"], "correctIndex": 1, "explanation": "SIM swapping allows attackers to steal your phone number remotely and receive your SMS authentication codes."}]'::jsonb,
 5),

('d1000000-0000-0000-0000-000000000004',
 'Social Media Privacy & Digital Footprint Minimization',
 'privacy-footprint',
 'Privacy',
 'Learn how attackers use open-source intelligence (OSINT) to compromise security questions and impersonate you.',
 '{"sections": [{"title": "Open Source Intelligence (OSINT)", "body": "Attackers collect publicly available info from your posts—like childhood pet names, mother maiden name, high school, and birthday—to answer account recovery security questions."}, {"title": "Privacy Lockdown Strategies", "items": ["Restrict birthdate visibility to month and day, hiding birth year.", "Do not post high-resolution photos of identity cards or event tickets with barcodes.", "Keep friends lists private to block clone/impersonation scams."]}]}'::jsonb,
 '[{"question": "How do attackers use publicly visible birthdates and pet posts?", "options": ["To send spam emails", "To answer security reset questions and craft targeted social engineering scams", "To slow down internet speed", "To delete your photos"], "correctIndex": 1, "explanation": "Information shared online is often used by cybercriminals to bypass password recovery questions or build convincing fake profiles."}]'::jsonb,
 7);
